// Guard de tipo de evento: solo BOOKING_CREATED debe crear evento en Google
// Calendar. Cal.com puede enviar tambien BOOKING_REQUESTED / CANCELLED /
// RESCHEDULED / REJECTED; si el workflow los procesara, crearia eventos
// incorrectos en GCal (ver ONIA_N8N_TELEGRAM_CLEANUP_20260630.md, problema #4
// y "Salida objetivo pendiente" en ONIA_CALCOM_SELF_HOST_RUNBOOK_2026.md).
const body = $input.first().json.body || $input.first().json;
const triggerEvent = body.triggerEvent || (body.payload && body.payload.triggerEvent) || '';
if (triggerEvent && triggerEvent !== 'BOOKING_CREATED') {
  // Ignorar silenciosamente cualquier otro evento: no crear GCal, no notificar.
  return [];
}
const payload = body.payload || body;
const attendees = payload.attendees || [];
const attendeeName = attendees[0] && attendees[0].name ? attendees[0].name : 'Cliente';
const attendeeEmail = attendees[0] && attendees[0].email ? attendees[0].email : '';
const titulo = payload.title || ('Reunion con ' + attendeeName);
return [{
  json: {
    titulo,
    startISO: payload.startTime,
    endISO: payload.endTime,
    descripcion: (payload.description || '') + '\nCliente: ' + attendeeName + ' (' + attendeeEmail + ')',
    attendeeName,
    attendeeEmail
  }
}];

const parsed = $input.first().json;
const startStr = parsed.startISO ? new Date(parsed.startISO).toLocaleString('es-BO', { timeZone: 'America/La_Paz', weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
const msg = '📅 <b>Nueva reunión agendada por cliente</b>\n\n' +
  '👤 ' + parsed.attendeeName + (parsed.attendeeEmail ? ' (' + parsed.attendeeEmail + ')' : '') + '\n' +
  '📋 ' + parsed.titulo + '\n' +
  '⏰ ' + startStr + '\n' +
  '🗓️ Evento creado en tu Google Calendar por Cal.';
const destinatarios = ['6830070978', '8887222181'];
return destinatarios.map(chatId => ({ json: { mensaje: msg, chatId } }));

// [DESHABILITADO] Validacion de firma del webhook Cal.com. Activar SOLO cuando
// el secret este seteado en Cal admin Y en n8n. Pasos:
// 1) Cal admin (cal.onia.com.bo/settings/developer/webhooks): generar/pegar secret.
// 2) n8n: cargar env var CALCOM_WEBHOOK_SECRET con ese mismo valor.
// 3) Habilitar este nodo.
// Cal firma con X-Cal-Signature-256 = HMAC-SHA256(body crudo, secret).
// NOTA: el HMAC es sobre el body CRUDO. Si la firma no coincide, habilitar
// "Raw Body" en el nodo Webhook y usar el string crudo aca y en el parse.
const crypto = require("crypto");
const secret = $env.CALCOM_WEBHOOK_SECRET;
if (!secret) { throw new Error("Falta CALCOM_WEBHOOK_SECRET en n8n"); }
const headers = $json.headers || {};
const sig = headers["x-cal-signature-256"] || headers["X-Cal-Signature-256"] || "";
const raw = typeof $json.body === "string" ? $json.body : JSON.stringify($json.body);
const expected = crypto.createHmac("sha256", secret).update(raw).digest("hex");
if (sig !== expected) { throw new Error("Firma Cal invalida"); }
return $input.all();
